// SearchHeader.js
import React from 'react';
import { useTranslation } from 'react-i18next';

const SearchHeader = ({ onTitleClick }) => {
    const { t } = useTranslation();

    const monthKey = 1; // TODO: remove hardcoded variable
    const year = 2025; // TODO: remove hardcoded variable
  return (
    <>
      <h1>
        <button
          onClick={onTitleClick}
          style={{
            cursor: "pointer",
            color: "inherit",
            background: "none",
            border: "none",
            fontSize: "1em",
            textDecoration: "overline",
          }}
        >
          {t("welcome")}
        </button>
      </h1>
      <h2>
        {t("searchSong")}{" "}
        <span role="img" aria-label="emoji">
          🎤
        </span>
      </h2>
        <p>
          {t("description", {
            month: t(`months.${monthKey}`),
            year,
          })}
        </p>
        <p>
          [ FR=France, ITA=Italy, DE=Germany, ES=Spain, PHL=Philippines, ROU=Romania, PRT=Portugal, CN=Chinese ]
        </p>
    </>
  );
};

export default SearchHeader;